package com.andye.warmod.antiair;import com.andye.warmod.antiair.network.*;import com.andye.warmod.radar.*;import com.andye.warmod.silo.MissileSiloCollisionContext;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.attribute.EnvironmentAttributes;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;public final class AntiAirLaunchService{private AntiAirLaunchService(){}public static Vec3 estimatedBurnout(ServerLevel l,Vec3 origin){double cloud=origin.y;try{cloud=l.environmentAttributes().getValue(EnvironmentAttributes.CLOUD_HEIGHT,origin).doubleValue();}catch(RuntimeException ignored){}return new Vec3(origin.x,Math.max(origin.y+96,cloud+48),origin.z);}public static Optional<AntiAirLaunchResult> launchFromSilo(ServerLevel l,@Nullable UUID owner,String name,UUID siloId,BlockPos centre,Vec3 origin,AntiAirMissileVariant variant,AntiAirTargetLock lock,AntiAirInterceptSolution solution,int tier,MissileSiloCollisionContext collision){return launch(l,owner,name,siloId,centre,origin,estimatedBurnout(l,origin),variant,lock,solution,tier,false,collision);}public static Optional<AntiAirLaunchResult> launchDebug(ServerLevel l,@Nullable UUID owner,String name,Vec3 origin,AntiAirMissileVariant variant,@Nullable AntiAirTargetLock lock,@Nullable AntiAirInterceptSolution solution){Vec3 burnout;if(lock==null){double y=origin.y>=AntiAirConstants.DEBUG_NO_TARGET_CEILING_Y?origin.y+128:AntiAirConstants.DEBUG_NO_TARGET_CEILING_Y;burnout=new Vec3(origin.x,y,origin.z);}else burnout=estimatedBurnout(l,origin);return launch(l,owner,name,null,null,origin,burnout,variant,lock,solution,3,lock==null,new MissileSiloCollisionContext(UUID.randomUUID(),BlockPos.containing(origin),Set.of(),.35,2.2));}private static Optional<AntiAirLaunchResult> launch(ServerLevel l,@Nullable UUID owner,String name,@Nullable UUID siloId,@Nullable BlockPos centre,Vec3 origin,Vec3 burnout,AntiAirMissileVariant variant,@Nullable AntiAirTargetLock lock,@Nullable AntiAirInterceptSolution solution,int tier,boolean debug,MissileSiloCollisionContext collision){if(!AntiAirFlightControllerManager.canAccept(l)||!origin.isFinite()||!burnout.isFinite()||(!debug&&(lock==null||solution==null)))return Optional.empty();UUID id=UUID.randomUUID();long seed=id.getMostSignificantBits()^Long.rotateLeft(id.getLeastSignificantBits(),19);AntiAirFlightPlan plan=new AntiAirFlightPlan(id,owner,siloId,centre,variant,lock==null?null:lock.rootTrackId(),origin,burnout,lock,solution,l.getGameTime(),AntiAirConstants.IGNITION_TICKS,AntiAirConstants.BOOST_TICKS,seed,tier,debug);if(!AntiAirFlightControllerManager.add(l,plan,collision))return Optional.empty();RadarInterceptorPlanSnapshot radar=new RadarInterceptorPlanSnapshot(variant,Optional.ofNullable(plan.targetRootTrackId()),origin,burnout,plan.launchGameTime(),plan.ignitionTicks(),plan.boostTicks(),tier,AntiAirGuidanceResolver.maximumMiss(tier),Optional.empty());RadarTrackingService.registerInterceptor(l,id,owner,name,radar);AntiAirNetworking.send(l,new ClientboundAntiAirLaunchPayload(id,owner,variant,plan.targetRootTrackId(),origin,burnout,plan.launchGameTime(),plan.ignitionTicks(),plan.boostTicks(),seed,tier,debug));return Optional.of(new AntiAirLaunchResult(plan));}}